evidence.rules:
table inet ffx {
	map allow {
		type uid : verdict
	}

	chain output {
		type filter hook output priority filter; policy accept;
		meta skuid 800-831 jump pool
	}

	chain pool {
		oifname "lo" jump refuse
		meta skuid vmap @allow
		jump refuse
	}

	chain refuse {
		meta l4proto tcp counter packets 0 bytes 0 reject with tcp reset
		counter packets 0 bytes 0 drop
	}
}
